/** Every reserved name (with the simulator's KNOWN_RUNTIME_NAMES). */
export const RESERVED_NAMES: ReadonlySet<string> = new Set([...CPP_KEYWORDS, ...MACROS, ...DECLARATION_FAILURES, ...EMITTED_NAMES, ...KNOWN_RUNTIME_NAMES]);
